package com.ciaac.minecraft.minigames.knockbacksumo;
import static org.junit.jupiter.api.Assertions.*;import java.time.*;import java.util.*;import org.junit.jupiter.api.Test;
class SumoSessionTest{ @Test void ringOutIsIdempotencyProtectedAndProducesWinner(){UUID a=UUID.randomUUID(),b=UUID.randomUUID();var s=new SumoSession(UUID.randomUUID(),new SumoConfig("r1",2,2,1,Duration.ofSeconds(30)),a,b);s.start(Instant.EPOCH,UUID.randomUUID());s.ringOut(a,Instant.EPOCH.plusSeconds(1),UUID.randomUUID());assertEquals(b,s.result().orElseThrow().winner());assertThrows(IllegalStateException.class,()->s.ringOut(a,Instant.EPOCH,UUID.randomUUID()));}
 @Test void configuredRoundTimeoutProducesDeterministicDraw(){UUID a=UUID.randomUUID(),b=UUID.randomUUID(),event=UUID.randomUUID();var s=new SumoSession(UUID.randomUUID(),new SumoConfig("r1",2,2,2,Duration.ofSeconds(30)),a,b);s.start(Instant.EPOCH,UUID.randomUUID());assertFalse(s.roundTimedOut(Instant.EPOCH.plusSeconds(29)));assertTrue(s.roundTimedOut(Instant.EPOCH.plusSeconds(30)));s.timeout(Instant.EPOCH.plusSeconds(30),event);var result=s.result().orElseThrow();assertTrue(result.draw());assertEquals(a,result.winner());assertEquals(b,result.loser());assertEquals(1,result.rounds());assertThrows(IllegalStateException.class,()->s.timeout(Instant.EPOCH.plusSeconds(30),event));}}
